-- Esquema PostgreSQL do banco `imoveis` (compra e aluguel em tabelas separadas).
-- Convertido do MySQL (db/conf.sql + db/conf_aluguel.sql). Idempotente: pode rodar mais de uma vez.
--
-- Diferenças em relação ao MySQL:
--   AUTO_INCREMENT      -> GENERATED BY DEFAULT AS IDENTITY
--   float               -> DOUBLE PRECISION
--   tinyint(1)          -> BOOLEAN
--   ENUM(...)           -> TEXT + CHECK
--   ON UPDATE CURRENT_TIMESTAMP (city_metadata) -> não existe no Postgres; atualizar last_updated no UPDATE
--   Nomes sem aspas viram minúsculos: parkingSpaces -> parkingspaces (o SQL da aplicação continua funcionando)

-- ============================================================
-- Compra (Ponta Grossa)
-- ============================================================
CREATE TABLE IF NOT EXISTS predicoes (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    area_m2              DOUBLE PRECISION,
    endereco             VARCHAR(255),
    banheiros            INTEGER,
    quartos              INTEGER,
    vagas_garagem        INTEGER,
    tipo_imovel_cat      VARCHAR(50),
    is_sobrado           INTEGER DEFAULT 0,
    score_escola_privada DOUBLE PRECISION,
    score_escola_publica DOUBLE PRECISION,
    score_farmacia       DOUBLE PRECISION,
    score_hospitais      DOUBLE PRECISION,
    score_mercado        DOUBLE PRECISION,
    score_parque         DOUBLE PRECISION,
    score_seguranca      DOUBLE PRECISION,
    preco_anuncio        DOUBLE PRECISION,
    preco_predito        DOUBLE PRECISION,
    erro_absoluto        DOUBLE PRECISION,
    erro_percentual      DOUBLE PRECISION,       -- fração (0.15 = 15%)
    modelo               VARCHAR(100),
    versao_modelo        VARCHAR(50),
    created_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS features_monitoramento (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    predicao_id          INTEGER REFERENCES predicoes(id),
    area_m2              DOUBLE PRECISION,
    score_escola_privada DOUBLE PRECISION,
    score_escola_publica DOUBLE PRECISION,
    score_farmacia       DOUBLE PRECISION,
    score_hospitais      DOUBLE PRECISION,
    score_mercado        DOUBLE PRECISION,
    score_parque         DOUBLE PRECISION,
    score_seguranca      DOUBLE PRECISION,
    created_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_features_predicao ON features_monitoramento (predicao_id);

-- ============================================================
-- Aluguel (São Paulo)
-- ============================================================
CREATE TABLE IF NOT EXISTS predicoes_aluguel (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    endereco             VARCHAR(255),
    bairro               VARCHAR(120),
    latitude             NUMERIC(10,7),
    longitude            NUMERIC(10,7),
    tipo_imovel_cat      VARCHAR(50),
    area                 DOUBLE PRECISION,
    bedrooms             INTEGER,
    bathrooms            INTEGER,
    suites               INTEGER,
    parkingSpaces        INTEGER,
    mobiliado            INTEGER DEFAULT 0,
    am_ar_condicionado   INTEGER DEFAULT 0,
    inst_piscina         INTEGER DEFAULT 0,
    inst_academia        INTEGER DEFAULT 0,
    am_varanda           INTEGER DEFAULT 0,
    aluguel_anuncio      DOUBLE PRECISION,
    aluguel_predito      DOUBLE PRECISION,
    pct_custo_extra      DOUBLE PRECISION,
    custo_total_estimado DOUBLE PRECISION,
    erro_absoluto        DOUBLE PRECISION,
    erro_percentual      DOUBLE PRECISION,       -- fração (0.15 = 15%)
    modelo               VARCHAR(100),
    versao_modelo        VARCHAR(50),
    origem               VARCHAR(20),            -- 'individual' ou 'lote'
    created_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_aluguel_created ON predicoes_aluguel (created_at);
CREATE INDEX IF NOT EXISTS idx_aluguel_versao ON predicoes_aluguel (modelo, versao_modelo);

CREATE TABLE IF NOT EXISTS features_monitoramento_aluguel (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    predicao_id          INTEGER REFERENCES predicoes_aluguel(id),
    bedrooms             DOUBLE PRECISION,
    bathrooms            DOUBLE PRECISION,
    parkingSpaces        DOUBLE PRECISION,
    area                 DOUBLE PRECISION,
    suites               DOUBLE PRECISION,
    score_escola_privada DOUBLE PRECISION,
    score_escola_publica DOUBLE PRECISION,
    score_hospitais      DOUBLE PRECISION,
    score_mercado        DOUBLE PRECISION,
    score_farmacia       DOUBLE PRECISION,
    score_parque         DOUBLE PRECISION,
    score_seguranca      DOUBLE PRECISION,
    score_metro          DOUBLE PRECISION,
    mobiliado            DOUBLE PRECISION,
    am_ar_condicionado   DOUBLE PRECISION,
    inst_piscina         DOUBLE PRECISION,
    inst_academia        DOUBLE PRECISION,
    am_varanda           DOUBLE PRECISION,
    dist_centro_km       DOUBLE PRECISION,
    dist_polo_km         DOUBLE PRECISION,
    created_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_features_aluguel_predicao ON features_monitoramento_aluguel (predicao_id);

-- ============================================================
-- Compartilhadas
-- ============================================================
CREATE TABLE IF NOT EXISTS metrics_monitoramento (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    metric_name   VARCHAR(100),
    metric_value  DOUBLE PRECISION,
    feature_name  VARCHAR(100),
    metric_type   VARCHAR(50),                   -- drift, performance
    modelo        VARCHAR(100),
    versao_modelo VARCHAR(50),
    created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS pois (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome       VARCHAR(255),
    tipo_poi   TEXT NOT NULL CHECK (tipo_poi IN ('mercado', 'farmacia', 'escola', 'hospital', 'parque', 'policia')),
    latitude   NUMERIC(10,7) NOT NULL,
    longitude  NUMERIC(10,7) NOT NULL,
    cidade     VARCHAR(120) NOT NULL,
    estado     CHAR(2),
    fonte      VARCHAR(100),                     -- ex: 'csv', 'osm', 'google'
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_poi_cidade ON pois (cidade);
CREATE INDEX IF NOT EXISTS idx_poi_tipo ON pois (tipo_poi);
CREATE INDEX IF NOT EXISTS idx_poi_lat_lon ON pois (latitude, longitude);

CREATE TABLE IF NOT EXISTS city_metadata (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city         VARCHAR(100) NOT NULL,
    state        VARCHAR(50) NOT NULL,
    country      VARCHAR(50) NOT NULL DEFAULT 'Brazil',
    pois_loaded  BOOLEAN DEFAULT FALSE,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    total_pois   INTEGER DEFAULT 0,
    CONSTRAINT unique_city UNIQUE (city, state, country)
);

-- Estatísticas por feature gravadas pelo job de drift (monitoring/jobs/run_data_drift.py)
-- e lidas pelo exporter do Prometheus. Não existia no MySQL: o job falhava ao gravar.
CREATE TABLE IF NOT EXISTS distribution_stats (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    feature_name  VARCHAR(100) NOT NULL,
    dataset_type  VARCHAR(20) NOT NULL,          -- 'baseline' ou 'production'
    mean_value    DOUBLE PRECISION,
    std_value     DOUBLE PRECISION,
    min_value     DOUBLE PRECISION,
    max_value     DOUBLE PRECISION,
    p25_value     DOUBLE PRECISION,
    p50_value     DOUBLE PRECISION,
    p75_value     DOUBLE PRECISION,
    sample_count  INTEGER,
    modelo        VARCHAR(100),
    versao_modelo VARCHAR(50),
    created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_distribution_feature ON distribution_stats (feature_name, dataset_type, created_at);
